pragma solidity ^0.8.24;

import {Test} from "forge-std/Test.sol";
import {PriceFeed} from "../../contracts/PriceFeed.sol";
import {FixedSource} from "../mocks/FixedSource.sol";

contract StalePriceTest is Test {
    function test_dayOldAnswerIsReturned() public {
        FixedSource source = new FixedSource(2000e8, block.timestamp);
        PriceFeed feed = new PriceFeed(source);
        vm.warp(block.timestamp + 1 days);
        assertEq(feed.latestPrice(), 2000e8);
    }
}
